  m.PlanAdvice(false);m.PlanAdvice(true);m.Dialogue(4);m.Save(after);Check(File.ReadAllText(before)==File.ReadAllText(after),"planning queries and rendering never mutate saved gameplay state");var loaded=new GameModel();Check(loaded.Load(after)&&loaded.S.Version==5&&loaded.PlanStock("pilă")[3]==1000000,"planner derives correct state after unchanged v5 reload");
